const lockVariantForUpdate = `-- name: LockVariantForUpdate :one
SELECT v.id, v.product_id, v.sku, v.option_value_ids, v.price_idr, v.compare_at_price_idr, v.stock, v.is_preorder, v.is_active, v.image_id, v.created_at, v.cost_idr, v.low_stock_threshold, v.barcode, p.slug AS product_slug, p.name AS product_name, p.is_active AS product_active, p.deleted_at AS product_deleted_at,
  p.category_id, p.brand_id, b.name AS brand_name,
  COALESCE(pi.url, (SELECT url FROM product_images WHERE product_id = p.id ORDER BY sort_order ASC LIMIT 1)) AS resolved_image_url
FROM variants v
JOIN products p ON p.id = v.product_id
JOIN brands b ON b.id = p.brand_id
LEFT JOIN product_images pi ON pi.id = v.image_id
WHERE v.id = $1
FOR UPDATE OF v
`

type LockVariantForUpdateRow struct {
	ID                uuid.UUID     `json:"id"`
	ProductID         uuid.UUID     `json:"product_id"`
	Sku               string        `json:"sku"`
	OptionValueIds    []uuid.UUID   `json:"option_value_ids"`
	PriceIdr          int64         `json:"price_idr"`
	CompareAtPriceIdr *int64        `json:"compare_at_price_idr"`
	Stock             int32         `json:"stock"`
	IsPreorder        bool          `json:"is_preorder"`
	IsActive          bool          `json:"is_active"`
	ImageID           uuid.NullUUID `json:"image_id"`
	CreatedAt         time.Time     `json:"created_at"`
	CostIdr           *int64        `json:"cost_idr"`
	LowStockThreshold int32         `json:"low_stock_threshold"`
	Barcode           *string       `json:"barcode"`
	ProductSlug       string        `json:"product_slug"`
	ProductName       string        `json:"product_name"`
	ProductActive     bool          `json:"product_active"`
	ProductDeletedAt  *time.Time    `json:"product_deleted_at"`
	CategoryID        uuid.UUID     `json:"category_id"`
	BrandID           uuid.UUID     `json:"brand_id"`
	BrandName         string        `json:"brand_name"`
	ResolvedImageUrl  string        `json:"resolved_image_url"`
}

func (q *Queries) LockVariantForUpdate(ctx context.Context, id uuid.UUID) (LockVariantForUpdateRow, error) {
	row := q.db.QueryRow(ctx, lockVariantForUpdate, id)
	var i LockVariantForUpdateRow
	err := row.Scan(
		&i.ID,
		&i.ProductID,
		&i.Sku,
		&i.OptionValueIds,
		&i.PriceIdr,
		&i.CompareAtPriceIdr,
		&i.Stock,
		&i.IsPreorder,
		&i.IsActive,
		&i.ImageID,
		&i.CreatedAt,
		&i.CostIdr,
		&i.LowStockThreshold,
		&i.Barcode,
		&i.ProductSlug,
		&i.ProductName,
		&i.ProductActive,
		&i.ProductDeletedAt,
		&i.CategoryID,
		&i.BrandID,
		&i.BrandName,
		&i.ResolvedImageUrl,
	)
	return i, err
}

